import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import ApiService from '../../Services/ApiService';

export default function InfluencerPosts() {
    const navigate = useNavigate();
    const [posts, setPosts] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        loadInfluencerPosts();
    }, []);

    const loadInfluencerPosts = async () => {
        try {
            setLoading(true);
            const response = await ApiService.getInfluencerReels();
            
            if (response.success) {
                setPosts(response.data || []);
            } else {
                toast.error(response.message || 'Failed to load posts');
                setPosts([]);
            }
        } catch (error) {
            console.error('Error loading posts:', error);
            toast.error('Failed to load posts: ' + (error.message || 'Unknown error'));
            setPosts([]);
        } finally {
            setLoading(false);
        }
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 'approved':
                return <span className="badge bg-success">Approved</span>;
            case 'pending':
                return <span className="badge bg-warning">Pending</span>;
            case 'rejected':
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    // Function to render video player for a reel
    const renderVideoPlayer = (reel) => {
        // Construct full URLs for video and thumbnail
        const baseUrl = window.location.origin;
        let fullVideoUrl = reel.video_url;
        let fullThumbnailUrl = reel.thumbnail;
        
        // Handle relative URLs
        if (reel.video_url && !reel.video_url.startsWith('http')) {
            fullVideoUrl = `${baseUrl}${reel.video_url}`;
        }
        
        if (reel.thumbnail && !reel.thumbnail.startsWith('http')) {
            fullThumbnailUrl = `${baseUrl}${reel.thumbnail}`;
        }
        
        if (!fullVideoUrl) {
            return <div className="alert alert-warning">No video available for this reel</div>;
        }
        
        return (
            <div className="video-player-container mb-4 border rounded p-3">
                <video 
                    width="100%" 
                    height="200" 
                    controls
                    poster={fullThumbnailUrl || ''}
                    className="rounded"
                >
                    <source src={fullVideoUrl} type="video/mp4" />
                    Your browser does not support the video tag.
                </video>
                <div className="mt-2">
                    <div className="d-flex align-items-center justify-content-between mb-2">
                        <h6 className="mb-0">{reel.title || 'Untitled Reel'}</h6>
                        <div>
                            {getStatusBadge(reel.status)}
                        </div>
                    </div>
                    <div className="d-flex justify-content-between align-items-center">
                        <div>
                            <span className="text-muted me-3">
                                <i className="ri-eye-line me-1"></i> {reel.views || 0}
                            </span>
                            <span className="text-muted">
                                <i className="ri-heart-line me-1"></i> {reel.likes || 0}
                            </span>
                        </div>
                    </div>
                </div>
            </div>
        );
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">My Posts</h4>
                    <button 
                        className="btn btn-outline-secondary"
                        onClick={() => navigate('/studio/influencer/profile')}
                    >
                        <i className="ri-arrow-left-line me-1"></i> Back to Profile
                    </button>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-body">
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border text-primary" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                                <p className="mt-2">Loading posts...</p>
                            </div>
                        ) : posts.length === 0 ? (
                            <div className="text-center py-5">
                                <i className="ri-image-line ri-3x text-muted"></i>
                                <h5 className="mt-3">No posts found</h5>
                                <p className="text-muted">You haven't uploaded any reels yet.</p>
                            </div>
                        ) : (
                            <div className="row">
                                {posts.map((post) => (
                                    <div key={post.id} className="col-md-6 col-lg-4 mb-4">
                                        {renderVideoPlayer(post)}
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
